#pragma once
// Embedded logo pixels (generated by scripts/embed_icons.py): straight-alpha RGBA, size*size*4 bytes each.
#include <stddef.h>
#include <stdint.h>

typedef struct ccord_icon_image {
  int size;
  const uint8_t *rgba;
} ccord_icon_image;

extern const ccord_icon_image ccord_app_icon_images[];   // ascending size: 16..256
extern const size_t ccord_app_icon_image_count;
extern const ccord_icon_image ccord_tray_icon_images[];  // 22, 24, 32, 48
extern const size_t ccord_tray_icon_image_count;
